
.statusbar-root {
  width: 100%;
  font-family: var(--font-sys);
}

.statusbar {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  font-family: var(--font-sys);
  font-size: 13px;
  line-height: 1.4;
  color: var(--c-text);
  background-color: var(--c-background);
  border: 2px solid var(--c-border);
  border-radius: 6px;
  overflow: hidden;
}

.titlebar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background-color: var(--c-surface);
  border-bottom: 1px solid var(--c-border);
  flex-wrap: wrap;
}

.meta-left,
.meta-right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.loc {
  color: var(--c-primary);
  font-weight: bold;
}

.time {
  color: var(--c-text);
  opacity: 0.85;
}

.money {
  color: var(--c-accent);
  font-weight: bold;
}

.schedule {
  color: var(--c-primary);
  font-weight: bold;
  font-size: 12px;
  padding: 2px 8px;
  border: 1px solid var(--c-primary);
  border-radius: 3px;
  background-color: color-mix(in srgb, var(--c-primary) 10%, var(--c-surface));

  i {
    margin-right: 4px;
  }
}

.tabs {
  display: flex;
  gap: 2px;
  border-bottom: 1px solid var(--c-border);
  padding: 0 4px;
  background-color: var(--c-background);

  .tab {
    flex: 1;
    padding: 8px 0;
    background: transparent;
    border: none;
    border-bottom: 2px solid transparent;
    color: var(--c-border);
    cursor: pointer;
    font-family: inherit;
    font-size: 13px;
    transition: color 0.2s ease, border-color 0.2s ease, background-color 0.2s ease;

    i {
      margin-right: 4px;
    }

    &:hover {
      color: var(--c-text);
      background-color: var(--c-surface);
    }

    &.active {
      color: var(--c-primary);
      border-bottom-color: var(--c-primary);
      font-weight: bold;
    }
  }
}

.content-area {
  padding: 12px;
  min-height: 0;
}

.panel-fade-enter-active,
.panel-fade-leave-active {
  transition: opacity 0.16s ease, transform 0.16s ease;
}

.panel-fade-enter-from {
  opacity: 0;
  transform: translateY(6px);
}

.panel-fade-leave-to {
  opacity: 0;
  transform: translateY(-6px);
}
