
.alchemist {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.stone-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--c-border);
  border-radius: 4px;
  background-color: var(--c-surface);

  &.owned {
    border-color: var(--c-mystic);
    background-color: color-mix(in srgb, var(--c-mystic) 7%, var(--c-surface));
  }
}

.stone-head {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--c-text);

  > i {
    color: var(--c-mystic);
  }

  .stone-title {
    color: var(--c-mystic);
  }

  .stone-num {
    margin-left: auto;
    font-size: 12px;
    font-weight: 700;
    color: var(--c-mystic);
  }
}

.stone-note {
  margin: 0;
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.8;

  b {
    color: var(--c-mystic);
  }
}

.stone-owned {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 9px;
  border: 1px solid var(--c-mystic);
  border-radius: 3px;
  background-color: color-mix(in srgb, var(--c-mystic) 12%, var(--c-surface));
  color: var(--c-mystic);
  font-size: 12px;
  font-weight: 600;

  i {
    font-size: 14px;
  }
}

.stone-tip {
  margin: 0;
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.65;
}

.stone-progress {
  display: flex;
  align-items: center;
  gap: 8px;

  .stone-bar {
    flex: 1;
    height: 10px;
    background-color: var(--c-background);
    border: 1px solid var(--c-border);
    border-radius: 3px;
    overflow: hidden;
  }

  .stone-fill {
    height: 100%;
    border-radius: 2px;
    background-color: var(--c-mystic);
    transition: width 0.35s ease;
  }

  .stone-count {
    flex-shrink: 0;
    font-size: 11px;
    font-weight: 600;
    opacity: 0.7;
  }

  &.ready .stone-fill {
    box-shadow: 0 0 6px rgba(91, 184, 166, 0.6);
  }
}

.stone-miss,
.stone-ok {
  margin: 0;
  font-size: 11px;
  line-height: 1.6;
}

.stone-miss {
  color: var(--c-danger);
  opacity: 0.85;
}

.stone-ok {
  color: var(--c-mystic);
}

.stone-btn {
  padding: 8px 0;
  border: 1px solid var(--c-mystic);
  border-radius: 4px;
  background-color: color-mix(in srgb, var(--c-mystic) 12%, var(--c-surface));
  color: var(--c-mystic);
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;

  i {
    margin-right: 6px;
  }

  &.armed {
    background-color: color-mix(in srgb, var(--c-danger) 16%, var(--c-surface));
    border-color: var(--c-danger);
    color: var(--c-danger);
  }

  &.disabled {
    opacity: 0.45;
    cursor: not-allowed;
  }
}

.stone-result {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-top: 4px;
  padding: 9px 10px;
  border: 1px solid var(--c-mystic);
  border-radius: 4px;
  background-color: color-mix(in srgb, var(--c-mystic) 6%, var(--c-surface));

  .result-title {
    font-size: 13px;
    font-weight: 700;
    color: var(--c-mystic);

    i {
      margin-right: 6px;
    }
  }

  .result-line {
    font-size: 12px;
    line-height: 1.5;

    .rk {
      display: inline-block;
      width: 40px;
      opacity: 0.6;
    }
  }
}

.receipt-box {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 5px;

  textarea {
    width: 100%;
    box-sizing: border-box;
    padding: 8px;
    border: 1px solid var(--c-border);
    border-radius: 4px;
    background-color: var(--c-background);
    color: var(--c-text);
    font-family: var(--font-mono);
    font-size: 11px;
    line-height: 1.5;
    resize: vertical;
  }
}

.copy-btn {
  padding: 6px 0;
  border: 1px solid var(--c-accent);
  border-radius: 4px;
  background-color: color-mix(in srgb, var(--c-accent) 12%, var(--c-surface));
  color: var(--c-accent);
  font-family: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;

  i {
    margin-right: 6px;
  }
}

.receipt-note {
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.6;
}
