
.npc-card {
  padding: 10px 12px;
  background-color: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 4px;
  cursor: pointer;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  user-select: none;

  &:hover {
    border-color: var(--c-primary);
  }
}

.npc-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.npc-name {
  flex: 1;
  min-width: 0;
  font-weight: bold;
  color: var(--c-text);

  i {
    margin-right: 4px;
    color: var(--c-border);
  }
}

.stage-badge {
  flex-shrink: 0;
  font-size: 11px;
  padding: 1px 8px;
  border-radius: 3px;
  color: var(--c-text);
  background-color: transparent;
  border: 1px solid var(--c-border);
}

.affection {
  flex-shrink: 0;
  font-size: 13px;
  font-weight: bold;
}

.aff-bar {
  height: 8px;
  background-color: var(--c-background);
  border: 1px solid var(--c-border);
  border-radius: 2px;
  overflow: hidden;
}

.aff-fill {
  height: 100%;
  border-radius: 1px;
  transition: width 0.35s ease, background-color 0.35s ease;
}

/* 好感度随关系阶段渐暖 */
.stage-0 .aff-fill {
  background-color: var(--c-aff-stage0);
}

.stage-1 .aff-fill {
  background-color: var(--c-aff-stage1);
}

.stage-2 .aff-fill {
  background-color: var(--c-aff-stage2);
}

.stage-3 .aff-fill {
  background-color: var(--c-aff-stage3);
}

.stage-0 .affection {
  color: var(--c-aff-stage0);
}

.stage-1 .affection {
  color: var(--c-aff-stage1);
}

.stage-2 .affection {
  color: var(--c-aff-stage2);
}

.stage-3 .affection {
  color: var(--c-aff-stage3);
}

.npc-detail {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed var(--c-border);
  font-size: 12px;
  color: var(--c-text);
  opacity: 0.9;

  p {
    margin-bottom: 4px;

    i {
      margin-right: 5px;
      color: var(--c-primary);
    }
  }
}

.detail-fade-enter-active,
.detail-fade-leave-active {
  transition: opacity 0.14s ease;
}

.detail-fade-enter-from,
.detail-fade-leave-to {
  opacity: 0;
}
