
.craft-root {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.craft-head {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  color: var(--c-text);

  > i {
    color: var(--c-primary);
  }

  .craft-sub {
    margin-left: auto;
    font-size: 11px;
    font-weight: 400;
    opacity: 0.6;
  }
}

.craft-hint {
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.7;
}

/* ── 可折叠面板（配方表 / 材料） ── */
.pane {
  border: 1px solid var(--c-border);
  border-radius: 4px;
  background-color: var(--c-surface);
  overflow: hidden;
}

.pane-head {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 7px 10px;
  border: none;
  background: transparent;
  color: var(--c-text);
  font-family: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;

  > i:first-child {
    color: var(--c-primary);
    font-size: 12px;
  }

  &:hover {
    background-color: color-mix(in srgb, var(--c-primary) 6%, var(--c-surface));
  }

  .pane-title {
    letter-spacing: 0.5px;
  }

  .pane-count {
    padding: 0 6px;
    border-radius: 8px;
    background-color: var(--c-background);
    font-size: 10px;
    font-weight: 600;
    opacity: 0.75;
  }
}

.chev {
  margin-left: auto;
  font-size: 10px;
  opacity: 0.55;
  transform: rotate(-90deg);
  transition: transform 0.18s ease;

  &.on {
    transform: rotate(0deg);
  }
}

.pane-body {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 10px 9px;
}

/* ── 配方表 ── */
.rp-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
}

.rp-tab {
  padding: 2px 7px;
  border: 1px solid var(--c-border);
  border-radius: 3px;
  background-color: var(--c-background);
  color: var(--c-text);
  font-family: inherit;
  font-size: 11px;
  cursor: pointer;

  &:hover {
    border-color: var(--c-accent);
  }

  &.on {
    border-color: var(--c-accent);
    background-color: color-mix(in srgb, var(--c-accent) 14%, var(--c-surface));
    color: var(--c-accent);
    font-weight: 600;
  }
}

.rp-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  max-height: 118px;
  overflow-y: auto;
}

.rp-chip {
  padding: 3px 8px;
  border: 1px solid var(--c-border);
  border-radius: 3px;
  background-color: var(--c-background);
  color: var(--c-text);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
  transition: border-color 0.15s ease, background-color 0.15s ease;

  &:hover {
    border-color: var(--c-accent);
  }

  &.on {
    border-color: var(--c-accent);
    background-color: color-mix(in srgb, var(--c-accent) 14%, var(--c-surface));
    color: var(--c-accent);
    font-weight: 600;
  }
}

.rp-info {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 3px;
  background-color: color-mix(in srgb, var(--c-accent) 8%, var(--c-background));
  font-size: 11px;
  line-height: 1.5;

  .rp-info-name {
    flex-shrink: 0;
    font-weight: 700;
    color: var(--c-accent);
  }

  .rp-info-eff {
    flex: 1;
    opacity: 0.85;
  }

  .rp-clear {
    flex-shrink: 0;
    padding: 2px 6px;
    border: 1px solid var(--c-border);
    border-radius: 3px;
    background-color: var(--c-surface);
    color: var(--c-text);
    font-family: inherit;
    font-size: 11px;
    cursor: pointer;

    &:hover {
      border-color: var(--c-danger);
      color: var(--c-danger);
    }
  }
}

/* ── 材料：按药效分类折叠 ── */
.picked-row {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 5px 6px;
  border-radius: 3px;
  background-color: color-mix(in srgb, var(--c-primary) 8%, var(--c-background));
}

.picked-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border: 1px solid var(--c-primary);
  border-radius: 3px;
  background-color: var(--c-surface);
  color: var(--c-primary);
  font-family: inherit;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;

  i {
    font-size: 9px;
    opacity: 0.7;
  }

  &:hover i {
    opacity: 1;
    color: var(--c-danger);
  }
}

.sec {
  display: flex;
  flex-direction: column;
  gap: 3px;

  & + .sec {
    margin-top: 4px;
  }
}

.sec-name {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--c-primary);

  .sec-count {
    padding: 0 5px;
    border-radius: 7px;
    background-color: var(--c-background);
    font-size: 9px;
    font-weight: 600;
    opacity: 0.7;
  }
}

.eff-head {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 3px 6px;
  border: none;
  border-radius: 3px;
  background: transparent;
  color: var(--c-text);
  font-family: inherit;
  font-size: 11px;
  text-align: left;
  cursor: pointer;

  &:hover {
    background-color: color-mix(in srgb, var(--c-text) 6%, var(--c-surface));
  }

  .eff-name {
    flex-shrink: 0;
    font-weight: 600;
  }

  .eff-desc {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 10px;
    opacity: 0.6;
  }

  .eff-num {
    flex-shrink: 0;
    font-size: 10px;
    opacity: 0.5;
  }

  .chev {
    flex-shrink: 0;
  }
}

.mat-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 2px 0 2px 8px;
}

.mat-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border: 1px solid var(--c-border);
  border-radius: 3px;
  background-color: var(--c-background);
  color: var(--c-text);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
  transition: border-color 0.15s ease, background-color 0.15s ease;

  &:hover {
    border-color: var(--c-primary);
  }

  &.picked {
    border-color: var(--c-primary);
    background-color: color-mix(in srgb, var(--c-primary) 14%, var(--c-surface));
    font-weight: 600;
  }

  &.disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }

  .mat-stock {
    font-size: 10px;
    opacity: 0.65;

    &.zero {
      color: var(--c-danger);
    }
  }
}

/* ── 基底与炼制 ── */
.base-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;

  .base-label {
    font-size: 12px;
    font-weight: 600;
    color: var(--c-text);
  }
}

.base-chip {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  padding: 4px 9px;
  border: 1px solid var(--c-border);
  border-radius: 3px;
  background-color: var(--c-surface);
  color: var(--c-text);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;

  &:hover {
    border-color: var(--c-primary);
  }

  &.picked {
    border-color: var(--c-accent);
    background-color: color-mix(in srgb, var(--c-accent) 14%, var(--c-surface));
    color: var(--c-accent);
    font-weight: 600;
  }

  .base-form {
    font-size: 10px;
    opacity: 0.6;
  }
}

.stone-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;

  &.off .stone-chip {
    opacity: 0.5;
  }
}

.stone-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border: 1px solid var(--c-border);
  border-radius: 3px;
  background-color: var(--c-surface);
  color: var(--c-text);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;

  i {
    color: var(--c-mystic);
  }

  &:hover:not(:disabled) {
    border-color: var(--c-mystic);
  }

  &.on {
    border-color: var(--c-mystic);
    background-color: color-mix(in srgb, var(--c-mystic) 14%, var(--c-surface));
    color: var(--c-mystic);
    font-weight: 600;
  }

  &:disabled {
    cursor: not-allowed;
  }
}

.craft-bar {
  display: flex;
  align-items: center;
  gap: 10px;
}

.sel-note {
  font-size: 11px;
  opacity: 0.75;

  .warn {
    color: var(--c-warn);
  }
}

.craft-btn {
  flex: 1;
  padding: 7px 0;
  border: none;
  border-radius: 4px;
  background-color: var(--c-primary);
  color: var(--c-text);
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;

  i {
    margin-right: 6px;
  }

  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
  }
}

.conflict-box {
  padding: 7px 10px;
  border: 1px solid var(--c-danger);
  border-radius: 4px;
  background-color: color-mix(in srgb, var(--c-danger) 10%, var(--c-surface));
  color: var(--c-danger);
  font-size: 12px;

  i {
    margin-right: 6px;
  }
}

.result-box {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 9px 10px;
  border: 1px solid var(--c-primary);
  border-radius: 4px;
  background-color: color-mix(in srgb, var(--c-primary) 6%, var(--c-surface));

  .result-title {
    font-size: 13px;
    font-weight: 700;
    color: var(--c-primary);

    i {
      margin-right: 6px;
    }
  }

  .result-line {
    font-size: 12px;
    color: var(--c-text);
    line-height: 1.5;

    .rk {
      display: inline-block;
      width: 40px;
      flex-shrink: 0;
      opacity: 0.6;
    }

    &.consume {
      opacity: 0.85;
    }

    &.transmute {
      color: var(--c-mystic);
      font-weight: 600;
    }

    &.stored {
      color: var(--c-primary);
      opacity: 0.9;
    }
  }
}

.receipt-box {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 5px;

  textarea {
    width: 100%;
    box-sizing: border-box;
    padding: 8px;
    border: 1px solid var(--c-border);
    border-radius: 4px;
    background-color: var(--c-background);
    color: var(--c-text);
    font-family: var(--font-mono);
    font-size: 11px;
    line-height: 1.5;
    resize: vertical;
  }
}

.copy-btn {
  padding: 6px 0;
  border: 1px solid var(--c-accent);
  border-radius: 4px;
  background-color: color-mix(in srgb, var(--c-accent) 12%, var(--c-surface));
  color: var(--c-accent);
  font-family: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;

  i {
    margin-right: 6px;
  }
}

.receipt-note {
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.6;
}
