
.workshop-root {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.workshop-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(112px, 1fr));
  gap: 6px;
}

.stat-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
  padding: 8px 10px;
  background-color: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 4px;
  color: var(--c-text);

  > i {
    color: var(--c-primary);
    font-size: 14px;
  }

  .label {
    font-size: 11px;
    opacity: 0.75;
  }

  .value {
    font-size: 15px;
    font-weight: bold;
    color: var(--c-text);
  }

  &.money .value {
    color: var(--c-accent);
  }

  &.good .value {
    color: var(--c-good, #6fae6f);
  }

  &.evil .value {
    color: var(--c-danger);
  }
}

.stock-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;

  @media (max-width: 360px) {
    grid-template-columns: 1fr;
  }
}

.customer-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 12px;
  background-color: color-mix(in srgb, var(--c-primary) 8%, var(--c-surface));
  border: 1px solid var(--c-primary);
  border-radius: 4px;

  &.empty {
    border-color: var(--c-border);
    border-style: dashed;
    background-color: var(--c-surface);

    .customer-head,
    .customer-need {
      opacity: 0.55;
    }
  }

  .customer-head {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    font-weight: 700;
    color: var(--c-primary);

    > i {
      font-size: 15px;
    }
  }

  .customer-label {
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.5px;
  }

  .customer-name {
    font-size: 13px;
    font-weight: 700;
  }

  .customer-tag {
    margin-left: auto;
    font-size: 10px;
    font-weight: 400;
    opacity: 0.65;
  }

  .customer-need {
    font-size: 12px;
    color: var(--c-text);
    line-height: 1.5;
  }
}

.stock-block,
.recipe-block {
  background-color: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 4px;
  padding: 7px 9px;
}

.stock-head {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text);
  margin-bottom: 5px;

  > i {
    color: var(--c-primary);
    font-size: 13px;
  }

  .count {
    margin-left: auto;
    font-size: 11px;
    opacity: 0.6;
  }
}

.chip-list {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  max-height: 132px;
  overflow-y: auto;

  .empty {
    opacity: 0.5;
    font-size: 11px;
  }
}

.stock-chip {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  padding: 3px 8px;
  border: 1px solid var(--c-border);
  border-radius: 3px;
  background-color: var(--c-background);
  color: var(--c-text);
  font-size: 12px;

  b {
    font-size: 10px;
    font-weight: 600;
    color: var(--c-accent);
    opacity: 0.9;
  }

  &.potion b {
    color: var(--c-primary);
  }
}

.recipe-chip {
  padding: 3px 8px;
  border: 1px solid var(--c-border);
  border-radius: 3px;
  background-color: var(--c-background);
  color: var(--c-text);
  font-size: 12px;
  cursor: help;
}
